                                            title={getStepDisplayName(step)}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                if (step.type === 'exercise') {
                                                    onInspectExercise(step.name);
                                                }
                                            }}
                                            style={{ cursor: step.type === 'exercise' ? 'pointer' : 'default' }}
                                        >
                                            <span className={`w-1.5 h-4 rounded ${step.type === 'exercise' ? 'bg-orange-400' : 'bg-transparent'}`}></span>
                                            <span className="truncate">{getStepDisplayName(step)} - <span className="text-gray-400 font-normal">{step.isRepBased ? `${step.reps} חזרות` : `${step.duration} שניות`}</span></span>
                                        </li>
                                    ))}
                                </ol>
                            </div>
                        )}
                     </div>
                 )}
            </div>
          </>
      )}

      {selectedPlanIds.length > 0 && !activeWorkout && (
          <button
            onClick={handleStartSelected}
            className="w-full mb-4 py-2.5 bg-green-600 text-white font-bold rounded-lg hover:bg-green-700 transition-colors"
          >
              Start Selected ({selectedPlanIds.length})
          </button>
      )}

      <div className="space-y-4">
        {plans.length === 0 ? (
          <p className="text-gray-400 text-center py-8">No workout plans yet. Create one to get started!</p>
        ) : (
          plans.map((plan, index) => (
            <PlanListItem 
                key={plan.id} 
                plan={plan} 
                index={index}
                setRef={el => { if (el) planRefs.current[plan.id] = el; }}
                onSelectPlan={() => onSelectPlan(plan)}
                onInitiateDelete={onInitiateDelete}
                onInspectExercise={onInspectExercise}
                onShowInfo={onShowInfo}
                onShare={handleShare}
                isSelected={selectedPlanIds.includes(plan.id)}
                onToggleSelection={handleToggleSelection}
                isDraggable={!activeWorkout}
                onDragStart={onDragStart}
                onDragOver={onDragOver}
                onDrop={onDrop}
                onDragEnd={onDragEnd}
                onDragLeave={onDragLeave}
                isDragTarget={dragTargetIndex === index}
                isNewlyImported={plan.id === recentlyImportedPlanId}
            />
          ))
        )}
      </div>
    </div>
  );
};

const AiPlannerModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onImportPlan: (plan: WorkoutPlan) => void;
}> = ({ isOpen, onClose, onImportPlan }) => {
    const { settings } = useSettings();
    const [messages, setMessages] = useState<{ role: 'user' | 'model'; text: string; plan?: WorkoutPlan }[]>([]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Initial greeting
    useEffect(() => {
        if (isOpen && messages.length === 0) {
             setMessages([{ role: 'model', text: "היי! אני מאמן הכושר האישי שלך. ספר לי על המטרות שלך, הציוד שיש לך, וכמה זמן יש לך לאימון, ואני אבנה לך תוכנית מותאמת אישית." }]);
        }
    }, [isOpen, messages.length]);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [messages]);

    const handleSendMessage = async () => {
        if (!input.trim() || isLoading) return;

        const userMsg = input.trim();
        setInput('');
        setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
        setIsLoading(true);

        // Prepare history for API
        const apiHistory = messages.map(m => ({
            role: m.role,
            parts: [{ text: m.text }]
        }));

        // Prepare context from user settings
        let profileContext = "";
        if (settings.userProfile) {
            if (settings.userProfile.fitnessLevel) profileContext += `Fitness Level: ${settings.userProfile.fitnessLevel}\n`;
            if (settings.userProfile.equipment && settings.userProfile.equipment.some(e => e.available)) {
                const availableEq = settings.userProfile.equipment.filter(e => e.available).map(e => e.name).join(', ');
                profileContext += `Available Equipment: ${availableEq}\n`;
            }
        }

        try {
            const responseText = await generateWorkoutPlan(apiHistory, userMsg, profileContext);

            // Try to extract JSON plan
            let extractedPlan: WorkoutPlan | undefined;
            let displayText = responseText;

            const jsonMatch = responseText.match(/```json\s*([\s\S]*?)\s*```/);
            if (jsonMatch) {
                try {
                    const jsonStr = jsonMatch[1];
                    const planData = JSON.parse(jsonStr);
                    // Validate basic structure
                    if (planData.name && Array.isArray(planData.steps)) {
                         extractedPlan = {
                             ...planData,
                             id: `ai_${Date.now()}`,
                             steps: planData.steps.map((s: any, i: number) => ({
                                 ...s,
                                 id: `ai_step_${Date.now()}_${i}`
                             })),
                             isSmartPlan: true,
                         } as WorkoutPlan;
                    }
                    // Remove the JSON block from display text to keep it clean
                    displayText = responseText.replace(/```json[\s\S]*?```/, '').trim();
                } catch (e) {
                    console.error("Failed to parse AI plan JSON", e);
                }
            }

            setMessages(prev => [...prev, { role: 'model', text: displayText, plan: extractedPlan }]);

        } catch (error) {
             console.error("AI Planner Error:", error);
             setMessages(prev => [...prev, { role: 'model', text: "מצטער, נתקלתי בבעיה בחיבור לשרת. אנא נסה שוב מאוחר יותר." }]);
        } finally {
            setIsLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/80 z-[150] flex items-center justify-center p-4" onClick={onClose}>
            <div className="bg-gray-800 rounded-lg shadow-2xl w-full max-w-2xl h-[80vh] flex flex-col" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center p-4 border-b border-gray-700">
                    <h3 className="text-xl font-bold text-white flex items-center gap-2">
                        <span>✨</span> AI Workout Planner
                    </h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-white">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                <div className="flex-grow overflow-y-auto p-4 space-y-4">
                    {messages.map((msg, idx) => (
                        <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                            <div 
                                className={`max-w-[85%] rounded-lg p-3 whitespace-pre-wrap ${
                                    msg.role === 'user' 
                                    ? 'bg-blue-600 text-white rounded-br-none' 
                                    : 'bg-gray-700 text-gray-200 rounded-bl-none'
                                }`}
                            >
                                {msg.text}
                            </div>
                            {msg.plan && (
                                <div className="mt-2 bg-gray-900 rounded-lg p-3 border border-purple-500/30 w-full max-w-sm">
                                    <h4 className="font-bold text-white mb-1">{msg.plan.name}</h4>
                                    <p className="text-xs text-gray-400 mb-3">{msg.plan.steps.length} steps</p>
                                    <button 
                                        onClick={() => {
                                            onImportPlan(msg.plan!);
                                            onClose();
                                        }}
                                        className="w-full py-2 bg-purple-600 hover:bg-purple-700 text-white rounded font-semibold text-sm transition-colors"
                                    >
                                        Import This Plan
                                    </button>
                                </div>
                            )}
                        </div>
                    ))}
                    {isLoading && (
                        <div className="flex justify-start">
                            <div className="bg-gray-700 rounded-lg p-3 rounded-bl-none flex gap-2 items-center">
                                <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></span>
                                <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-100"></span>
                                <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-200"></span>
                            </div>
                        </div>
                    )}
                    <div ref={messagesEndRef} />
                </div>

                <div className="p-4 border-t border-gray-700 bg-gray-800 rounded-b-lg">
                    <div className="flex gap-2">
                        <input
                            type="text"
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                            placeholder="Describe your workout goal..."
                            className="flex-grow bg-gray-900 text-white border border-gray-600 rounded-full px-4 py-2 focus:outline-none focus:border-blue-500"
                            autoFocus
                        />
                        <button 
                            onClick={handleSendMessage}
                            disabled={isLoading || !input.trim()}
                            className="p-2 bg-blue-600 text-white rounded-full hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
                            </svg>
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void; }> = ({ isOpen, setIsOpen }) => {
    const { 
        plans, 
        savePlan, 
        deletePlan, 
        importPlan,
        isPreparingWorkout 
    } = useWorkout();
    const { settings, updateSettings } = useSettings();
    const [inspectedExercise, setInspectedExercise] = useState<string | null>(null);
    const [infoPlan, setInfoPlan] = useState<WorkoutPlan | null>(null);
    const [isLogVisible, setIsLogVisible] = useState(false);
    const [isPinned, setIsPinned] = useState(false);
    const [isAiPlannerOpen, setIsAiPlannerOpen] = useState(false);
    const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const [isEditorMode, setIsEditorMode] = useState(false);
    const [editingPlan, setEditingPlan] = useState<WorkoutPlan | null>(null);

    // Editor State
    const [editorName, setEditorName] = useState('');
    const [editorSteps, setEditorSteps] = useState<WorkoutStep[]>([]);

    const handleInspectExercise = (exerciseName: string) => {
        setInspectedExercise(exerciseName);
    };

    const handleCreateNew = () => {
        setEditorName('New Workout');
        setEditorSteps([]);
        setEditingPlan(null); // Null means creating new
        setIsEditorMode(true);
    };

    const handleEditPlan = (plan: WorkoutPlan) => {
        // Special case for warmup settings
        if (plan.id === '_warmup_') {
            setEditorName('Warm-up Routine');
            setEditorSteps([...settings.warmupSteps]);
            setEditingPlan({ id: '_warmup_', name: 'Warm-up Routine', steps: settings.warmupSteps, isRepBased: false } as any);
        } else {
            setEditorName(plan.name);
            setEditorSteps([...plan.steps]); // Shallow copy steps array
            setEditingPlan(plan);
        }
        setIsEditorMode(true);
    };

    const handleEditorSave = () => {
        if (!editorName.trim()) {
            alert("Please enter a plan name.");
            return;
        }
        if (editorSteps.length === 0) {
            alert("Please add at least one step.");
            return;
        }

        const newSteps = editorSteps.map((step, index) => ({
            ...step,
            id: step.id || `step_${Date.now()}_${index}` // Ensure IDs
        }));

        if (editingPlan?.id === '_warmup_') {
             updateSettings({ warmupSteps: newSteps });
        } else {
            const planToSave: WorkoutPlan = editingPlan ? {
                ...editingPlan,
                name: editorName,
                steps: newSteps,
                version: 2
            } : {
                id: `plan_${Date.now()}`,
                name: editorName,
                steps: newSteps,
                executionMode: 'linear',
                version: 2
            };
            savePlan(planToSave);
        }
        setIsEditorMode(false);
        clearEditorDraft();
    };

    const handleEditorCancel = () => {
        if (confirm("Discard changes?")) {
            setIsEditorMode(false);
            clearEditorDraft();
        }
    };

    // Draft Auto-Save
    useEffect(() => {
        if (isEditorMode) {
            const draft: WorkoutPlan = {
                id: editingPlan?.id || 'draft',
                name: editorName,
                steps: editorSteps,
                version: 2
            };
            saveEditorDraft(draft);
        }
    }, [isEditorMode, editorName, editorSteps, editingPlan]);

    // Restore Draft
    useEffect(() => {
        if (!isEditorMode && isOpen) {
             const draft = getEditorDraft();
             if (draft) {
                 // Optional: Ask user if they want to restore? For now just log or ignore.
                 // A real implementation might show a "Resume editing?" prompt.
             }
        }
    }, [isOpen, isEditorMode]);


    // Step Editor inside the Menu
    const addStep = (type: 'exercise' | 'rest') => {
        const newStep: WorkoutStep = {
            id: `temp_${Date.now()}`,
            name: type === 'exercise' ? 'New Exercise' : 'Rest',
            type,
            isRepBased: false,
            duration: type === 'rest' ? settings.defaultRestDuration : settings.defaultExerciseDuration,
            reps: 10,
        };
        setEditorSteps([...editorSteps, newStep]);
    };

    const updateStep = (index: number, updates: Partial<WorkoutStep>) => {
        const newSteps = [...editorSteps];
        newSteps[index] = { ...newSteps[index], ...updates };
        setEditorSteps(newSteps);
    };

    const removeStep = (index: number) => {
        const newSteps = [...editorSteps];
        newSteps.splice(index, 1);
        setEditorSteps(newSteps);
    };

    const moveStep = (index: number, direction: -1 | 1) => {
        if ((index === 0 && direction === -1) || (index === editorSteps.length - 1 && direction === 1)) return;
        const newSteps = [...editorSteps];
        const temp = newSteps[index];
        newSteps[index] = newSteps[index + direction];
        newSteps[index + direction] = temp;
        setEditorSteps(newSteps);
    };

    // Auto-Close Logic
    const handleClose = useCallback(() => {
        setIsOpen(false);
        setIsPinned(false);
        setInfoPlan(null);
        setIsLogVisible(false);
        if (!isEditorMode) {
             // Only reset editor if not active, or handle via cancel
        }
    }, [setIsOpen, isEditorMode]);

    const handleMouseEnter = () => {
        if (closeTimerRef.current) {
            clearTimeout(closeTimerRef.current);
            closeTimerRef.current = null;
        }
    };

    const handleMouseLeave = () => {
        if (isOpen && !isPinned && !isEditorMode && !isLogVisible && !infoPlan && !inspectedExercise && !isAiPlannerOpen) {
            closeTimerRef.current = setTimeout(() => {
                handleClose();
            }, 5000);
        }
    };

    const touchStartX = useRef<number | null>(null);
    const touchEndX = useRef<number | null>(null);

    const handleTouchStart = (e: React.TouchEvent) => {
      touchEndX.current = null;
      touchStartX.current = e.touches[0].clientX;
    };

    const handleTouchMove = (e: React.TouchEvent) => {
      touchEndX.current = e.touches[0].clientX;
    };

    const handleTouchEnd = () => {
      if (!touchStartX.current || !touchEndX.current) return;
      const distance = touchStartX.current - touchEndX.current; // Swiping Left closes (since menu is on left)
      if (distance > 50) {
          handleClose();
      }
      touchStartX.current = null;
      touchEndX.current = null;
    };

    // Editor UI Component
    const Editor = () => (
        <div className="flex flex-col h-full animate-fadeIn">
            <div className="flex justify-between items-center mb-4 pb-4 border-b border-gray-700">
                <h3 className="text-xl font-bold text-white">{editingPlan ? 'Edit Plan' : 'New Plan'}</h3>
                 <div className="flex gap-2">
                    <button onClick={handleEditorCancel} className="p-2 text-gray-400 hover:text-white">Cancel</button>
                    <button onClick={handleEditorSave} className="px-4 py-1 bg-blue-600 text-white rounded font-bold hover:bg-blue-700">Save</button>
                </div>
            </div>

            <div className="mb-4">
                <label className="block text-xs text-gray-400 mb-1">Plan Name</label>
                <input 
                    type="text" 
                    value={editorName} 
                    onChange={e => setEditorName(e.target.value)} 
                    className="w-full bg-gray-900 text-white p-2 rounded border border-gray-600 focus:border-blue-500 outline-none"
                    placeholder="e.g. Full Body HIIT"
                />
            </div>

