                         {step.type === 'rest' && (
                             <div className="flex items-center gap-1 text-sm">
                                  <input 
                                    type="number" 
                                    value={step.duration} 
                                    onChange={e => updateStep(index, { duration: parseInt(e.target.value)||0 })}
