            <div className="absolute bottom-0 left-0 right-0 p-4 bg-gray-800 border-t border-gray-700 flex gap-2">
                <button onClick={() => addStep('exercise')} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded font-semibold">+ Exercise</button>
                <button onClick={() => addStep('rest')} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded font-semibold">+ Rest</button>
