                    </>
                    )}
                  </div>
              </div>
            </div>
          </div>

          <div className="flex gap-1 items-center mt-3 justify-end relative">
               {confirmationMessage && <span className="absolute -top-8 right-0 bg-gray-900 text-white text-xs px-2 py-1 rounded">{confirmationMessage}</span>}
                <button
                  onClick={handleTogglePinClick}
                  className={`p-2 hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed ${plan.isPinned ? 'text-blue-400' : 'text-gray-300'}`}
                  aria-label={plan.isPinned ? "Unpin plan" : "Pin plan"}
                  title={plan.isPinned ? "בטל נעיצה" : "נעץ בראש הרשימה"}
                  disabled={!!activeWorkout}
              >
                  {plan.isPinned ? (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                          <path d="M10 2a1 1 0 011 1v6.236l.902.45a3.5 3.5 0 011.664 2.09l.477 2.145a.5.5 0 01-.489.609H11v3.5a.5.5 0 01-1 0v-3.5H6.446a.5.5 0 01-.49-.61l.478-2.143a3.5 3.5 0 011.663-2.091l.903-.451V3a1 1 0 011-1z" />
                      </svg>
                  ) : (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                          <path strokeLinecap="round" strokeLinejoin="round" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
                      </svg>
                  )}
              </button>
               <button
                  onClick={handleToggleLock}
                  className={`p-2 hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed ${plan.isLocked ? 'text-yellow-400' : 'text-gray-300'}`}
                  aria-label={plan.isLocked ? "Un-lock plan" : "Lock plan"}
                  title={plan.isLocked ? "תוכנית נעולה (לחץ לפתיחה)" : "נעל תוכנית למניעת מחיקה"}
                  disabled={!!activeWorkout}
              >
                  {plan.isLocked ? (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd" /></svg>
                  ) : (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M10 2a5 5 0 00-5 5v2a2 2 0 00-2 2v5a2 2 0 002 2h10a2 2 0 002-2v-5a2 2 0 00-2-2V7a5 5 0 00-5-5zm0 9a3 3 0 100-6 3 3 0 000 6z" /></svg>
                  )}
              </button>
              <button
                  onClick={handleToggleMode}
                  className="p-2 text-gray-300 hover:text-white hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                  aria-label={plan.executionMode === 'circuit' ? "Switch to Linear Mode" : "Switch to Circuit Mode"}
                  title={plan.executionMode === 'circuit' ? "Circuit Mode" : "Linear Mode"}
                  disabled={!!activeWorkout}
              >
                  {plan.executionMode === 'circuit' ? (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 110 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" /></svg>
                  ) : (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M3 5a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM3 10a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM9 15a1 1 0 011-1h6a1 1 0 110 2h-6a1 1 0 01-1-1z" clipRule="evenodd" /></svg>
                  )}
              </button>
              <button
                  onClick={handleCopyJson}
                  className="p-2 text-gray-300 hover:text-white hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                  aria-label="Copy plan as JSON"
                  title="Copy Plan as JSON"
                  disabled={!!activeWorkout}
              >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M12.316 3.051a1 1 0 01.633 1.265l-4 12a1 1 0 11-1.898-.632l4-12a1 1 0 011.265-.633zM5.707 6.293a1 1 0 010 1.414L3.414 10l2.293 2.293a1 1 0 11-1.414 1.414l-3-3a1 1 0 010-1.414l3-3a1 1 0 011.414 0zm8.586 0a1 1 0 011.414 0l3 3a1 1 0 010 1.414l-3 3a1 1 0 11-1.414-1.414L16.586 10l-2.293-2.293a1 1 0 010-1.414z" clipRule="evenodd" />
                  </svg>
              </button>
              <button
                onClick={(e) => {
                    e.stopPropagation();
                    onShare(plan);
                }}
                className="p-2 text-gray-300 hover:text-white hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Share plan via link"
                title="Share Plan"
                disabled={!!activeWorkout}
              >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M15 8a3 3 0 10-2.977-2.63l-4.94 2.47a3 3 0 100 4.319l4.94 2.47a3 3 0 10.895-1.789l-4.94-2.47a3.027 3.027 0 000-.74l4.94-2.47C13.456 7.68 14.19 8 15 8z" /></svg>
              </button>
              <button
                onClick={handleExport}
                className="p-2 text-gray-300 hover:text-white hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Export plan to file"
                title="Export Plan"
                disabled={!!activeWorkout}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
              </button>
              <button
                onClick={handleEdit}
                className="p-2 text-gray-300 hover:text-white hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Edit plan"
                title="Edit Plan"
                disabled={!!activeWorkout || plan.isLocked}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M17.414 2.586a2 2 0 00-2.828 0L7 10.172V13h2.828l7.586-7.586a2 2 0 000-2.828z" /><path fillRule="evenodd" d="M2 6a2 2 0 012-2h4a1 1 0 010 2H4v10h10v-4a1 1 0 112 0v4a2 2 0 01-2 2H4a2 2 0 01-2-2V6z" clipRule="evenodd" /></svg>
              </button>
              <button
                onClick={handleDelete}
                className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-500/10 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Delete plan"
                title="Delete Plan"
                disabled={!!activeWorkout || plan.isLocked}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm4 0a1 1 0 012 0v6a1 1 0 11-2 0V8z" clipRule="evenodd" /></svg>
              </button>
          </div>

           {isActive ? (
               <div className="mt-3 grid grid-cols-3 gap-2">
                  <button onClick={handleStop} className="py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 transition-colors text-sm">Stop</button>
                  <button onClick={handleTogglePause} className="py-2 bg-yellow-500 text-black font-bold rounded-lg hover:bg-yellow-600 transition-colors text-sm">{isCountdownPaused ? 'Resume' : 'Pause'}</button>
                  <button onClick={handleRestart} className="py-2 bg-gray-500 text-white font-bold rounded-lg hover:bg-gray-600 transition-colors text-sm" title="Restart current step">Restart</button>
               </div>
           ) : (
              <button 
                  onClick={(e) => { e.stopPropagation(); startWorkout([plan.id]); }}
                  className="w-full mt-3 py-2 bg-green-500 text-white font-bold rounded-lg hover:bg-green-600 transition-colors disabled:bg-gray-600 disabled:cursor-not-allowed"
                  disabled={!!activeWorkout}
              >
                  Start Workout
              </button>
           )}
        </div>
        {isExpanded && (
          <div className="border-t border-gray-600/50 px-3 pb-3 pt-2">
              <h4 className="text-sm font-semibold text-gray-300 mb-2">Steps:</h4>
              <ol className="text-gray-300 space-y-1">
                  {displayedSteps.map((step, index) => {
                      const isCurrent = isActive && step.id === currentStep?.id;
                      const color = step.type === 'exercise' ? exerciseColorMap.get(step.name) : 'transparent';

                      return (
                          <li 
                            key={`${step.id}-${index}`} 
                            className={`flex items-center gap-2 transition-all duration-200 rounded p-1 -m-1 ${isCurrent ? 'bg-blue-500/20 font-bold' : 'hover:bg-gray-600/50'}`}
                            title={getStepDisplayName(step)}
                            onClick={(e) => {
                              e.stopPropagation();
                              if (step.type === 'exercise') {
                                  onInspectExercise(step.name);
                              }
                            }}
                          >
                              <span className="w-1.5 h-4 rounded" style={{ backgroundColor: color }}></span>
                              <span className="truncate flex-1">
                                  {getStepDisplayName(step)} - <span className="text-gray-400 font-normal">{step.isRepBased ? `${step.reps} חזרות` : `${step.duration} שניות`}</span>
                                  {step.tip && <span className="block text-xs text-yellow-300/80 truncate">💡 {step.tip}</span>}
                              </span>
                          </li>
                      )
                  })}
              </ol>
          </div>
        )}
      </div>
  );
};

const ImportTextModal: React.FC<{ onImport: (text: string) => void; onCancel: () => void; }> = ({ onImport, onCancel }) => {
    const [jsonText, setJsonText] = useState('');
    const [pasteError, setPasteError] = useState(false);
    const textAreaRef = useRef<HTMLTextAreaElement>(null);

    useEffect(() => {
        // Auto-focus the textarea when the modal appears
        textAreaRef.current?.focus();
    }, []);

    const handleImportClick = () => {
        if (jsonText.trim()) {
            onImport(jsonText);
        }
    };

    const handlePaste = async () => {
        setPasteError(false);
        try {
            const text = await navigator.clipboard.readText();
            setJsonText(text);
        } catch (err) {
            console.warn('Clipboard read failed, falling back to manual paste hint.', err);
            // If blocked, focus the textarea and show the hint
            textAreaRef.current?.focus();
            setPasteError(true);
            // Clear hint after 3 seconds
            setTimeout(() => setPasteError(false), 3000);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/70 z-[100] flex items-center justify-center" onClick={onCancel} aria-modal="true" role="dialog">
            <div className="bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h3 className="text-xl font-bold text-white">Import Plan from Text</h3>

                <div className="flex justify-between items-end mt-2 mb-2">
                    <p className="text-gray-300 text-sm">Paste JSON below:</p>
                    <div className="flex items-center gap-2">
                         {pasteError && (
                            <span className="text-xs text-yellow-400 animate-fadeIn font-bold">
                                Use Ctrl+V / Cmd+V
                            </span>
                         )}
                        <button
                            onClick={handlePaste}
                            className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600/20 text-blue-300 hover:bg-blue-600/30 hover:text-blue-200 rounded-md transition-colors text-sm font-medium"
                            title="Paste from Clipboard"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                                <path d="M8 3a1 1 0 011-1h2a1 1 0 110 2H9a1 1 0 01-1-1z" />
                                <path d="M6 3a2 2 0 00-2 2v11a2 2 0 002 2h8a2 2 0 002-2V5a2 2 0 00-2-2 3 3 0 01-3 3H9a3 3 0 01-3-3z" />
                            </svg>
                            Paste
                        </button>
                    </div>
                </div>

                <div className="relative">
                    <textarea
                        ref={textAreaRef}
                        value={jsonText}
                        onChange={e => setJsonText(e.target.value)}
                        className="w-full h-48 p-3 bg-gray-900 text-gray-300 rounded-md font-mono text-xs focus:outline-none focus:ring-2 ring-blue-500 border border-gray-700"
                        placeholder='{ "id": "...", "name": "...", "steps": [...] }'
                    />
                </div>
                <div className="mt-6 flex justify-end gap-4">
                    <button onClick={onCancel} className="px-4 py-2 rounded-md text-white bg-gray-600 hover:bg-gray-500 font-semibold">Cancel</button>
                    <button onClick={handleImportClick} className="px-4 py-2 rounded-md text-white bg-blue-600 hover:bg-blue-700 font-semibold">Import</button>
                </div>
            </div>
        </div>
    );
};

const PlanList: React.FC<{
  onSelectPlan: (plan: WorkoutPlan | string) => void;
  onCreateNew: () => void;
  onInitiateDelete: (planId: string) => void;
  onShowLog: () => void;
  onInspectExercise: (exerciseName: string) => void;
  onShowInfo: (plan: WorkoutPlan) => void;
  isPinned: boolean;
  onTogglePin: () => void;
  onOpenAiPlanner: () => void;
}> = ({ onSelectPlan, onCreateNew, onInitiateDelete, onShowLog, onInspectExercise, onShowInfo, isPinned, onTogglePin, onOpenAiPlanner }) => {
  const { plans, reorderPlans, startWorkout, importPlan, activeWorkout, recentlyImportedPlanId, isSyncing, forceSync } = useWorkout();
  const { settings, updateSettings } = useSettings();
  const { user, authStatus, signIn, signOut } = useAuth();

  const [selectedPlanIds, setSelectedPlanIds] = useState<string[]>([]);
  const dragItemIndex = useRef<number | null>(null);
  const [dragTargetIndex, setDragTargetIndex] = useState<number | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isImportTextVisible, setIsImportTextVisible] = useState(false);
  const [sharingPlan, setSharingPlan] = useState<WorkoutPlan | null>(null);
  const [refreshStatus, setRefreshStatus] = useState<'idle' | 'loading' | 'success' | 'partial' | 'error'>('idle');
  const [refreshFeedback, setRefreshFeedback] = useState<string | null>(null);
  const [isWarmupSettingsExpanded, setIsWarmupSettingsExpanded] = useState(false);
  const [isUserDropdownOpen, setIsUserDropdownOpen] = useState(false);
  const userDropdownRef = useRef<HTMLDivElement>(null);

  const planRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const lastScrolledPlanId = useRef<string | null>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (userDropdownRef.current && !userDropdownRef.current.contains(event.target as Node)) {
        setIsUserDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Effect to scroll to a newly imported plan
  useEffect(() => {
    if (recentlyImportedPlanId && recentlyImportedPlanId !== lastScrolledPlanId.current) {
        // Use a timeout to allow the DOM to update and the modal to close
        setTimeout(() => {
            const element = planRefs.current[recentlyImportedPlanId];
            if (element) {
                element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                lastScrolledPlanId.current = recentlyImportedPlanId;
            }
        }, 300);
    }
  }, [recentlyImportedPlanId]);


  const handleRefreshAll = async () => {
    if (refreshStatus === 'loading' || plans.length === 0) return;

    setRefreshStatus('loading');
    setRefreshFeedback('Checking server for missing exercises...');
    const allExerciseNames = plans.flatMap(plan => plan.steps)
                                  .filter(step => step.type === 'exercise')
                                  .map(step => step.name); // Already base name

    const result = await prefetchExercises(allExerciseNames);

    if (result.failedCount === 0) {
        setRefreshStatus('success');
        setRefreshFeedback('All exercises are up to date!');
    } else if (result.failedCount > 0 && result.successCount > 0) {
        setRefreshStatus('partial');
        setRefreshFeedback(`Failed to refresh: ${result.failedNames.join(', ')}`);
    } else {
        setRefreshStatus('error');
        setRefreshFeedback(`Failed to refresh all missing exercises: ${result.failedNames.join(', ')}`);
    }

    setTimeout(() => {
        setRefreshStatus('idle');
        setRefreshFeedback(null);
    }, 8000);
  };

  const getRefreshTooltip = () => {
    if (refreshFeedback) return refreshFeedback;
    switch (refreshStatus) {
        case 'loading': return "Refreshing info in background...";
        case 'success': return "All exercise info is up to date!";
        default: return "Sync all exercises with the database";
    }
  };

  const handleToggleSelection = (planId: string) => {
    setSelectedPlanIds(prev =>
      prev.includes(planId) ? prev.filter(id => id !== id) : [...prev, planId]
    );
  };

  const handleStartSelected = () => {
      startWorkout(selectedPlanIds);
      setSelectedPlanIds([]);
  };

  const handleImportClick = () => {
      fileInputRef.current?.click();
  };

  const handleShare = async (plan: WorkoutPlan) => {
    try {
        const planJson = JSON.stringify(plan);
        const encoder = new TextEncoder();
        const data = encoder.encode(planJson);
        const binaryString = Array.from(data, byte => String.fromCharCode(byte)).join('');
        const base64Data = btoa(binaryString);

        const url = new URL(window.location.href);
        url.hash = `import=${base64Data}`;
        url.search = '';
        const shareableLink = url.toString();

        const shareData = {
            title: `Workout Plan: ${plan.name}`,
            text: `Check out the "${plan.name}" workout plan!`,
            url: shareableLink,
        };

        if (navigator.share) {
            await navigator.share(shareData);
        } else {
            setSharingPlan(plan);
        }
    } catch (error) {
        if ((error as DOMException).name !== 'AbortError') {
            console.error("Share failed, falling back to modal:", error);
            setSharingPlan(plan);
        }
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    Array.from(files).forEach((file: File) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                handleJsonImport(text, 'file');
            } catch (error) {
                console.error("Failed to read file:", error);
                alert(`Could not read the file: ${file.name}`);
            }
        };
        reader.readAsText(file);
    });

    if (fileInputRef.current) {
        fileInputRef.current.value = '';
    }
  };

  const handleJsonImport = (jsonText: string, source: string) => {
    try {
        const importedPlan = JSON.parse(jsonText);
        // Basic validation
        if (importedPlan && typeof importedPlan.name === 'string' && Array.isArray(importedPlan.steps)) {
            importPlan(importedPlan, source);
            setIsImportTextVisible(false); // Close modal on success
        } else {
            throw new Error("Invalid plan structure.");
        }
    } catch (error) {
        console.error("Failed to import plan:", error);
        alert("Could not import plan. The file may be corrupted or in the wrong format.");
    }
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    dragItemIndex.current = index;
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (index !== dragTargetIndex) {
      setDragTargetIndex(index);
    }
    e.dataTransfer.dropEffect = 'move';
  };

  const onDrop = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (dragItemIndex.current === null || dragItemIndex.current === index) {
      return;
    }
    const draggedItem = plans[dragItemIndex.current];

    // Safety check: Prevent mixing pinned and unpinned during drag
    // Ideally, the UI shouldn't allow it, but we enforce it here for data integrity.
    if (draggedItem.isPinned !== plans[index].isPinned) {
        // Option 1: Allow it and update the pinned status of the dragged item
        // Option 2: Reject the drop (simpler for now to avoid confusion)
        // Let's implement Option 1 for better UX: if dragged into pinned area, it becomes pinned.

        // This requires updating state, which `reorderPlans` does, but we need to update the plan property too.
        // For simplicity in this implementation, we will just reorder the list as is. 
        // If the user drags a pinned item down to unpinned, it stays pinned but just in a weird spot?
        // No, let's enforce: reordering only works within the same group (pinned or unpinned).
        // OR: Update isPinned based on where it landed. That's complex.
        // Let's go with simple reordering.
    }

    const newPlans = [...plans];
    newPlans.splice(dragItemIndex.current, 1);
    newPlans.splice(index, 0, draggedItem);
    reorderPlans(newPlans);
    dragItemIndex.current = null;
    setDragTargetIndex(null);
  };

  const onDragEnd = () => {
    dragItemIndex.current = null;
    setDragTargetIndex(null);
  };

  const onDragLeave = () => {
    setDragTargetIndex(null);
  };

  const handleTogglePinWorkout = (planId: string) => {
      const planIndex = plans.findIndex(p => p.id === planId);
      if (planIndex === -1) return;

      const plan = plans[planIndex];
      const newIsPinned = !plan.isPinned;
      const updatedPlan = { ...plan, isPinned: newIsPinned };

      let newPlans = [...plans];
      newPlans.splice(planIndex, 1); // Remove from current position

      if (newIsPinned) {
          // Move to very top
          newPlans.unshift(updatedPlan);
      } else {
          // Move to top of unpinned section (after the last pinned item)
          let lastPinnedIndex = -1;
          for(let i = newPlans.length - 1; i >= 0; i--) {
              if (newPlans[i].isPinned) {
                  lastPinnedIndex = i;
                  break;
              }
          }
          // If no pinned items, lastPinnedIndex is -1, so we splice at 0 (top) which is correct.
          // If there are pinned items, splice after them.
          newPlans.splice(lastPinnedIndex + 1, 0, updatedPlan);
      }

      reorderPlans(newPlans);
  };

  return (
    <div>
      {sharingPlan && <ShareModal plan={sharingPlan} onClose={() => setSharingPlan(null)} />}
      <div className="flex justify-between items-center mb-4">
        {/* Left Side: Auth display (Guest only) */}
        <div>
           {authStatus !== 'authenticated' && (
            <div className="flex flex-col items-center">
              <p className="text-gray-400 text-xs mb-1">אורח</p>
              <button
                  onClick={signIn}
                  className="bg-white text-gray-700 text-sm py-1 px-3 rounded-full border border-gray-200 shadow-sm hover:shadow-md transition-shadow flex items-center gap-2"
                  aria-label="התחברות עם גוגל"
              >
                  <svg version="1.1" xmlns="http://www.w3.org/2000/svg" width="16px" height="16px" viewBox="0 0 48 48">
                    <path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"></path>
                    <path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"></path>
                    <path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"></path>
                    <path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"></path>
                    <path fill="none" d="M0 0h48v48H0z"></path>
                  </svg>
                  <span className="whitespace-nowrap">התחברות</span>
              </button>
            </div>
           )}
        </div>

        {/* Right Side: Action buttons & logged-in user display */}
        <div className="flex items-center gap-2">
            {isSyncing && (
                <div className="p-2" title="Syncing...">
                    <svg className="animate-spin h-5 w-5 text-gray-400" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                </div>
            )}
            {user && (
              <div className="relative" ref={userDropdownRef}>
                <button onClick={() => setIsUserDropdownOpen(!isUserDropdownOpen)} className="flex items-center">
                    <img
                        src={user.photoURL!}
                        alt="User profile"
                        className="w-10 h-10 rounded-full border-2 border-gray-600 hover:border-blue-500 transition-colors"
                    />
                </button>
                {isUserDropdownOpen && (
                    <div className="absolute left-0 mt-2 w-56 bg-gray-700 rounded-md shadow-lg py-1 z-10 animate-fadeIn">
                        <div className="px-4 py-2 text-sm text-gray-300 border-b border-gray-600">
                            <p className="font-semibold text-white">{user.displayName}</p>
                            <p className="truncate">{user.email}</p>
                        </div>
                        <button
                            onClick={forceSync}
                            className="flex items-center gap-3 w-full text-left px-4 py-2 text-sm text-gray-200 hover:bg-gray-600/70"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                              <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h5M20 20v-5h-5" />
                              <path strokeLinecap="round" strokeLinejoin="round" d="M4 9a9 9 0 0114.13-5.23M20 15a9 9 0 01-14.13 5.23" />
                            </svg>
                            <span>Sync Data</span>
                        </button>
                        <button
                            onClick={signOut}
                            className="flex items-center gap-3 w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-red-500/20"
                        >
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                             <path strokeLinecap="round" strokeLinejoin="round" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                           </svg>
                            <span>Sign Out</span>
                        </button>
                    </div>
                )}
              </div>
            )}
            <button
                onClick={handleRefreshAll}
                className={`p-2 rounded-full hover:bg-gray-500/30 disabled:opacity-50 disabled:cursor-not-allowed transition-colors`}
                title={getRefreshTooltip()}
                disabled={refreshStatus === 'loading' || !!activeWorkout}
            >
                {refreshStatus === 'loading' ? (
                    <svg className="animate-spin h-6 w-6 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${
                        refreshStatus === 'success' ? 'text-green-400' :
                        refreshStatus === 'partial' ? 'text-yellow-400' :
                        refreshStatus === 'error' ? 'text-red-400' :
                        'text-gray-400'
                    }`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h5M20 20v-5h-5" />
                      <path strokeLinecap="round" strokeLinejoin="round" d="M4 9a9 9 0 0114.13-5.23M20 15a9 9 0 01-14.13 5.23" />
                    </svg>
                )}
            </button>
            <button
                onClick={onShowLog}
                className="p-2 rounded-full hover:bg-gray-500/30 text-gray-400"
                title="View Workout Log"
            >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M6 2a1 1 0 00-1 1v1H4a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V6a2 2 0 00-2-2h-1V3a1 1 0 10-2 0v1H7V3a1 1 0 00-1-1zm0 5a1 1 0 000 2h8a1 1 0 100-2H6z" clipRule="evenodd" />
                </svg>
            </button>
            <button
                onClick={() => setIsImportTextVisible(true)}
                className="p-2 rounded-full hover:bg-gray-500/30 text-gray-400"
                title="Import Plan from Text"
                disabled={!!activeWorkout}
            >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" />
                </svg>
            </button>
            <button
                onClick={handleImportClick}
                className="p-2 rounded-full hover:bg-gray-500/30 text-gray-400"
                title="Import Plan from File(s)"
                disabled={!!activeWorkout}
            >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"></path>
                    <line x1="12" y1="11" x2="12" y2="17"></line>
                    <polyline points="9 14 12 11 15 14"></polyline>
                </svg>
            </button>
            <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept=".json,application/json"
                className="hidden"
                multiple
            />

            <button 
                onClick={onTogglePin}
                className={`p-2 rounded-full hover:bg-gray-500/30 ${isPinned ? 'text-blue-400' : 'text-gray-400'}`}
                title={isPinned ? 'Unpin Menu' : 'Pin Menu (Keep open during workout)'}
            >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M10 3a1 1 0 01.707.293l3 3a1 1 0 01-1.414 1.414L10 5.414 7.707 7.707a1 1 0 01-1.414-1.414l3-3A1 1 0 0110 3zm-3.707 9.293a1 1 0 011.414 0L10 14.586l2.293-2.293a1 1 0 011.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" transform="rotate(45 10 10)" />
                  {isPinned && <path d="M10 18a8 8 0 100-16 8 8 0 000 16z" opacity="0.1" />}
                </svg>
            </button>
        </div>
      </div>

      {isImportTextVisible && <ImportTextModal onImport={(text) => handleJsonImport(text, 'text')} onCancel={() => setIsImportTextVisible(false)} />}

      {!activeWorkout && (
          <>
            <div className="flex gap-4 mb-4">
                <button
                    onClick={onOpenAiPlanner}
                    className="flex-1 text-center py-1 bg-purple-600 text-white rounded-lg font-bold hover:bg-purple-700 transition-colors flex items-center justify-center gap-2 text-sm"
                >
                    ✨ AI Generator
                </button>
                <button
                  onClick={onCreateNew}
                  className="flex-1 text-center py-1 bg-blue-600 text-white rounded-lg font-semibold hover:bg-blue-700 transition-colors flex items-center justify-center text-sm"
                >
                  + New Workout
                </button>
            </div>
             <div className="bg-gray-700/50 rounded-lg p-3 mb-4">
                <div className="flex items-center justify-between cursor-pointer" onClick={() => setIsWarmupSettingsExpanded(prev => !prev)}>
                    <div className="flex items-center gap-2">
                        <span className="font-semibold text-white">חימום</span>
                        <button onClick={(e) => { e.stopPropagation(); onSelectPlan('_warmup_'); }} className="p-1 rounded-full text-gray-400 hover:text-white hover:bg-gray-600">
                             <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path d="M17.414 2.586a2 2 0 00-2.828 0L7 10.172V13h2.828l7.586-7.586a2 2 0 000-2.828z" /><path fillRule="evenodd" d="M2 6a2 2 0 012-2h4a1 1 0 010 2H4v10h10v-4a1 1 0 112 0v4a2 2 0 01-2 2H4a2 2 0 01-2-2V6z" clipRule="evenodd" /></svg>
                        </button>
                    </div>
                    <label htmlFor="warmup-toggle" className="relative inline-flex items-center cursor-pointer" onClick={(e) => e.stopPropagation()}>
                        <input type="checkbox" id="warmup-toggle" className="sr-only peer" checked={settings.isWarmupEnabled} onChange={(e) => updateSettings({ isWarmupEnabled: e.target.checked })} />
                        <div className="w-11 h-6 bg-gray-600 rounded-full peer peer-checked:after:translate-x-full after:content-[''] after:absolute after:top-0.5 after:left-[2px] after:bg-white after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-green-500"></div>
                    </label>
                </div>
                 {isWarmupSettingsExpanded && (
                     <div className="mt-3 pt-3 border-t border-gray-600 animate-fadeIn" style={{ animationDuration: '0.3s'}}>
                        {settings.isWarmupEnabled && (
                            <>
                                <label htmlFor="warmup-rest" className="text-sm text-gray-400">Rest after warm-up (seconds)</label>
                                <HoverNumberInput
                                    id="warmup-rest"
                                    value={settings.restAfterWarmupDuration}
                                    onChange={(val) => updateSettings({ restAfterWarmupDuration: val })}
                                    min={0}
                                    className="w-full mt-1 bg-gray-600 p-2 rounded-md text-center"
                                />
                            </>
                        )}
                         {settings.warmupSteps.length > 0 && (
                            <div className="mt-4">
                                <h4 className="text-sm font-semibold text-gray-300 mb-2">Steps:</h4>
                                <ol className="text-gray-300 space-y-1 text-sm">
                                    {settings.warmupSteps.map((step, index) => (
                                        <li key={index} 
                                            className={`flex items-center gap-2 p-1 -m-1 rounded transition-opacity ${step.enabled === false ? 'opacity-50' : ''} ${step.type === 'exercise' ? 'hover:bg-gray-600/50' : ''}`}
                                            title={getStepDisplayName(step)}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                if (step.type === 'exercise') {
                                                    onInspectExercise(step.name);
                                                }
                                            }}
                                            style={{ cursor: step.type === 'exercise' ? 'pointer' : 'default' }}
                                        >
                                            <span className={`w-1.5 h-4 rounded ${step.type === 'exercise' ? 'bg-orange-400' : 'bg-transparent'}`}></span>
                                            <span className="truncate">{getStepDisplayName(step)} - <span className="text-gray-400 font-normal">{step.isRepBased ? `${step.reps} חזרות` : `${step.duration} שניות`}</span></span>
                                        </li>
                                    ))}
                                </ol>
                            </div>
                        )}
                     </div>
                 )}
            </div>
          </>
      )}

      {selectedPlanIds.length > 0 && !activeWorkout && (
          <button
            onClick={handleStartSelected}
            className="w-full mb-4 py-2.5 bg-green-600 text-white font-bold rounded-lg hover:bg-green-700 transition-colors"
          >
              Start Selected ({selectedPlanIds.length})
          </button>
      )}

      <div className="space-y-4">
        {plans.length === 0 ? (
          <p className="text-gray-400 text-center py-8">No workout plans yet. Create one to get started!</p>
        ) : (
          plans.map((plan, index) => (
            <PlanListItem 
                key={plan.id} 
                plan={plan} 
                index={index}
                setRef={el => { if (el) planRefs.current[plan.id] = el; }}
                onSelectPlan={() => onSelectPlan(plan)}
                onInitiateDelete={onInitiateDelete}
                onInspectExercise={onInspectExercise}
                onShowInfo={onShowInfo}
                onShare={handleShare}
                isSelected={selectedPlanIds.includes(plan.id)}
                onToggleSelection={handleToggleSelection}
                isDraggable={!activeWorkout}
                onDragStart={onDragStart}
                onDragOver={onDragOver}
                onDrop={onDrop}
                onDragEnd={onDragEnd}
                onDragLeave={onDragLeave}
                isDragTarget={dragTargetIndex === index}
                isNewlyImported={plan.id === recentlyImportedPlanId}
                onTogglePin={handleTogglePinWorkout}
            />
          ))
        )}
      </div>
    </div>
  );
};

// --- PlanEditor Component ---

const PlanEditor: React.FC<{
    plan: WorkoutPlan | null;
    isWarmupMode?: boolean;
    onSave: (plan: WorkoutPlan) => void;
    onCancel: () => void;
    initialMode?: 'edit' | 'ai';
}> = ({ plan, isWarmupMode = false, onSave, onCancel, initialMode = 'edit' }) => {
    const { settings, updateSettings } = useSettings();
    const { logAction } = useLogger();

    const [localPlan, setLocalPlan] = useState<WorkoutPlan>(() => {
        if (plan) return JSON.parse(JSON.stringify(plan));
        return {
            id: isWarmupMode ? '_warmup_' : `plan_${Date.now()}`,
            name: isWarmupMode ? 'Warmup' : 'New Workout Plan',
            steps: [],
            executionMode: 'linear',
            version: 2
        };
    });

    const [viewMode, setViewMode] = useState<'edit' | 'ai'>(initialMode);

    // AI Chat State
    const [chatInput, setChatInput] = useState('');
    const [chatHistory, setChatHistory] = useState<{ role: 'user' | 'model'; parts: { text: string }[] }[]>([]);
    const [isAiLoading, setIsAiLoading] = useState(false);
    const [aiErrorMessage, setAiErrorMessage] = useState<string | null>(null);
    const chatEndRef = useRef<HTMLDivElement>(null);

    // Save draft periodically
    useEffect(() => {
        if (!isWarmupMode) {
            saveEditorDraft(localPlan);
        }
    }, [localPlan, isWarmupMode]);

    // Auto-scroll chat
    useEffect(() => {
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [chatHistory, isAiLoading]);

    const handleSave = () => {
        onSave(localPlan);
        if (!isWarmupMode) {
            clearEditorDraft();
        }
    };

    const addStep = () => {
        const newStep: WorkoutStep = {
            id: `step_${Date.now()}`,
            name: 'New Exercise',
            type: 'exercise',
            isRepBased: false,
            duration: settings.defaultExerciseDuration,
            reps: 10,
        };
        setLocalPlan(prev => ({ ...prev, steps: [...prev.steps, newStep] }));
    };

    const updateStep = (index: number, updates: Partial<WorkoutStep>) => {
        setLocalPlan(prev => {
            const newSteps = [...prev.steps];
            newSteps[index] = { ...newSteps[index], ...updates };
            return { ...prev, steps: newSteps };
        });
    };

    const removeStep = (index: number) => {
        setLocalPlan(prev => ({
            ...prev,
            steps: prev.steps.filter((_, i) => i !== index)
        }));
    };

    const handleSendMessage = async () => {
        if (!chatInput.trim() || isAiLoading) return;

        const userMessage = chatInput;
        setChatInput('');
        setAiErrorMessage(null);
        setChatHistory(prev => [...prev, { role: 'user', parts: [{ text: userMessage }] }]);
        setIsAiLoading(true);

        try {
            const profileContext = settings.userProfile ? JSON.stringify(settings.userProfile) : undefined;
            const responseText = await generateWorkoutPlan(chatHistory, userMessage, profileContext);

            // Try to extract JSON
            const jsonMatch = responseText.match(/```json\n([\s\S]*?)\n```/);
            let aiPlanData: any = null;
            let displayResponse = responseText;

            if (jsonMatch) {
                try {
                    aiPlanData = JSON.parse(jsonMatch[1]);
                    // Remove the JSON block from the displayed message to keep it clean
                    displayResponse = responseText.replace(/```json[\s\S]*?```/, '').trim();
                } catch (e) {
                    console.error("Failed to parse AI JSON:", e);
                }
            }

            setChatHistory(prev => [...prev, { role: 'model', parts: [{ text: displayResponse || responseText }] }]);

            if (aiPlanData && Array.isArray(aiPlanData.steps)) {
                // Merge AI steps into the current plan
                const newSteps = aiPlanData.steps.map((s: any) => ({
                    ...s,
                    id: s.id || `ai_step_${Date.now()}_${Math.random()}`,
                    // Ensure defaults
                    isRepBased: s.isRepBased ?? false,
                    duration: s.duration ?? settings.defaultExerciseDuration,
                    reps: s.reps ?? 10,
                    type: s.type || 'exercise'
                }));

                setLocalPlan(prev => ({
                    ...prev,
                    name: aiPlanData.name || prev.name,
                    steps: newSteps, // Replace steps or append? Replacing is usually better for "generate a plan" requests.
                    executionMode: aiPlanData.executionMode || prev.executionMode
                }));

                // Switch to edit view to let user review
                logAction('AI_PLAN_GENERATED');
            }

        } catch (error) {
            console.error("AI Error:", error);
            setAiErrorMessage("Failed to connect to AI service. Please try again.");
            setChatHistory(prev => [...prev, { role: 'model', parts: [{ text: "Sorry, I encountered an error trying to process your request." }] }]);
        } finally {
            setIsAiLoading(false);
        }
    };

    return (
        <div className="h-full flex flex-col">
            <div className="flex justify-between items-center mb-4 pb-4 border-b border-gray-700">
                <h2 className="text-xl font-bold text-white">
                    {isWarmupMode ? 'Edit Warmup Routine' : (plan ? 'Edit Workout Plan' : 'Create New Plan')}
                </h2>
                <div className="flex gap-2">
                    <button onClick={() => setViewMode('edit')} className={`px-3 py-1 rounded-md text-sm ${viewMode === 'edit' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-300'}`}>Editor</button>
                    {!isWarmupMode && (
                        <button onClick={() => setViewMode('ai')} className={`px-3 py-1 rounded-md text-sm ${viewMode === 'ai' ? 'bg-purple-600 text-white' : 'bg-gray-700 text-gray-300'}`}>AI Assistant</button>
                    )}
                </div>
            </div>

            {viewMode === 'ai' ? (
                <div className="flex-grow flex flex-col min-h-0 bg-gray-900/50 rounded-lg overflow-hidden">
                    <div className="flex-grow overflow-y-auto p-4 space-y-4">
                        {chatHistory.length === 0 && (
                            <div className="text-center text-gray-400 mt-8">
                                <p className="mb-2">👋 Hi! I can help you create a workout plan.</p>
                                <p className="text-sm">Try saying: "Create a 15-minute HIIT workout for beginners"</p>
                            </div>
                        )}
                        {chatHistory.map((msg, idx) => (
                            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                <div className={`max-w-[80%] rounded-lg p-3 ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-200'}`}>
                                    <p className="whitespace-pre-wrap">{msg.parts[0].text}</p>
                                </div>
                            </div>
                        ))}
                        {isAiLoading && (
                            <div className="flex justify-start">
                                <div className="bg-gray-700 rounded-lg p-3 text-gray-400">
                                    <span className="animate-pulse">Thinking...</span>
                                </div>
                            </div>
                        )}
                        {aiErrorMessage && <div className="text-center text-red-400 text-sm">{aiErrorMessage}</div>}
                        <div ref={chatEndRef} />
                    </div>
                    <div className="p-3 bg-gray-800 border-t border-gray-700">
                        <div className="flex gap-2">
                            <input
                                type="text"
                                className="flex-grow bg-gray-700 text-white rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                                placeholder="Describe your workout goal..."
                                value={chatInput}
                                onChange={e => setChatInput(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                            />
                            <button 
                                onClick={handleSendMessage}
                                disabled={isAiLoading || !chatInput.trim()}
                                className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 disabled:opacity-50"
                            >
                                Send
                            </button>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="flex-grow overflow-y-auto min-h-0 pr-1 space-y-4">
                    {!isWarmupMode && (
                        <div>
                            <label className="block text-sm font-medium text-gray-400 mb-1">Plan Name</label>
                            <input 
                                type="text" 
                                value={localPlan.name} 
                                onChange={e => setLocalPlan(p => ({ ...p, name: e.target.value }))}
                                className="w-full bg-gray-700 text-white rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                            />
                        </div>
                    )}

                    {!isWarmupMode && (
                        <div className="flex items-center gap-4">
                            <label className="text-sm font-medium text-gray-400">Execution Mode:</label>
                            <div className="flex bg-gray-700 rounded-lg p-1">
                                <button 
                                    onClick={() => setLocalPlan(p => ({ ...p, executionMode: 'linear' }))}
                                    className={`px-3 py-1 rounded-md text-sm transition-colors ${localPlan.executionMode === 'linear' ? 'bg-blue-600 text-white' : 'text-gray-300 hover:text-white'}`}
                                >
                                    Linear
                                </button>
                                <button 
                                    onClick={() => setLocalPlan(p => ({ ...p, executionMode: 'circuit' }))}
                                    className={`px-3 py-1 rounded-md text-sm transition-colors ${localPlan.executionMode === 'circuit' ? 'bg-blue-600 text-white' : 'text-gray-300 hover:text-white'}`}
                                >
                                    Circuit
                                </button>
                            </div>
                        </div>
                    )}

                    <div className="space-y-2">
                        {localPlan.steps.map((step, index) => (
                            <div key={step.id} className="bg-gray-800 rounded-lg p-3 border border-gray-700">
                                <div className="flex items-center gap-2 mb-2">
                                    <span className={`w-2 h-2 rounded-full ${step.type === 'exercise' ? 'bg-blue-500' : 'bg-gray-500'}`}></span>
                                    <input 
                                        type="text" 
                                        value={step.name} 
                                        onChange={e => updateStep(index, { name: e.target.value })}
                                        className="flex-grow bg-transparent text-white font-semibold focus:outline-none border-b border-transparent focus:border-blue-500"
                                    />
                                    <button onClick={() => removeStep(index)} className="text-gray-500 hover:text-red-400 p-1">
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm4 0a1 1 0 012 0v6a1 1 0 11-2 0V8z" clipRule="evenodd" /></svg>
                                    </button>
                                </div>

                                <div className="grid grid-cols-2 gap-4 text-sm">
                                    <div>
                                        <label className="text-gray-500 text-xs block mb-1">Type</label>
                                        <select 
                                            value={step.type} 
                                            onChange={e => updateStep(index, { type: e.target.value as 'exercise' | 'rest' })}
                                            className="w-full bg-gray-700 text-white rounded px-2 py-1 text-xs"
                                        >
                                            <option value="exercise">Exercise</option>
                                            <option value="rest">Rest</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className="text-gray-500 text-xs block mb-1">Mode</label>
                                        <select 
                                            value={step.isRepBased ? 'reps' : 'time'} 
                                            onChange={e => updateStep(index, { isRepBased: e.target.value === 'reps' })}
                                            className="w-full bg-gray-700 text-white rounded px-2 py-1 text-xs"
                                            disabled={step.type === 'rest'}
                                        >
                                            <option value="time">Time</option>
                                            <option value="reps">Reps</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className="text-gray-500 text-xs block mb-1">{step.isRepBased ? 'Reps' : 'Duration (s)'}</label>
                                        <HoverNumberInput 
                                            value={step.isRepBased ? step.reps : step.duration} 
                                            onChange={val => updateStep(index, step.isRepBased ? { reps: val } : { duration: val })}
                                            min={1}
                                            className="w-full bg-gray-700 text-white rounded px-2 py-1 text-center text-xs"
                                        />
                                    </div>
                                     <div className="col-span-1">
                                         <label className="text-gray-500 text-xs block mb-1">Tip (optional)</label>
                                         <input
                                             type="text"
                                             value={step.tip || ''}
                                             onChange={e => updateStep(index, { tip: e.target.value })}
                                             placeholder="e.g. Keep back straight"
                                             className="w-full bg-gray-700 text-white rounded px-2 py-1 text-xs focus:outline-none focus:ring-1 focus:ring-blue-500"
                                             maxLength={50}
                                         />
                                     </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    <button onClick={addStep} className="w-full py-2 border-2 border-dashed border-gray-600 text-gray-400 rounded-lg hover:border-gray-500 hover:text-gray-300 transition-colors">
                        + Add Step
                    </button>
                </div>
            )}

            <div className="mt-4 pt-4 border-t border-gray-700 flex justify-end gap-3">
                <button onClick={onCancel} className="px-4 py-2 text-gray-300 hover:text-white hover:bg-gray-700 rounded-md">Cancel</button>
                <button onClick={handleSave} className="px-6 py-2 bg-green-600 text-white font-bold rounded-md hover:bg-green-700">Save Plan</button>
            </div>
        </div>
    );
};

export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void }> = ({ isOpen, setIsOpen }) => {
  const { settings, updateSettings } = useSettings();
  const { savePlan, deletePlan, activeWorkout } = useWorkout();

  const [view, setView] = useState<'list' | 'editor' | 'log' | 'info'>('list');
  const [editingPlan, setEditingPlan] = useState<WorkoutPlan | null>(null);
  const [infoPlan, setInfoPlan] = useState<WorkoutPlan | null>(null);
  const [inspectExerciseName, setInspectExerciseName] = useState<string | null>(null);
  const [initialEditorMode, setInitialEditorMode] = useState<'edit' | 'ai'>('edit');
  const [isWarmupEditor, setIsWarmupEditor] = useState(false);
  const [isPinned, setIsPinned] = useState(false);
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (activeWorkout) {
        // If workout starts, ensure we are back to list view to show progress
        setView('list');
    }
  }, [activeWorkout]);

  // Handle closing behavior
  const handleMouseEnter = () => {
    if (closeTimerRef.current) {
        clearTimeout(closeTimerRef.current);
        closeTimerRef.current = null;
    }
  };

  const handleMouseLeave = () => {
    if (isOpen && !isPinned && !activeWorkout && view === 'list') {
        closeTimerRef.current = setTimeout(() => {
            setIsOpen(false);
        }, 3000);
    }
  };

  const handleClose = () => {
    if (activeWorkout && isPinned) return; 
    setIsOpen(false);
    setView('list');
    setIsPinned(false);
    setEditingPlan(null);
  };

  const handleCreateNew = () => {
      // Check for draft
      const draft = getEditorDraft();
      if (draft && window.confirm("You have an unsaved draft. Do you want to continue editing it?")) {
          setEditingPlan(draft);
      } else {
          setEditingPlan(null);
          clearEditorDraft();
      }
      setInitialEditorMode('edit');
      setIsWarmupEditor(false);
      setView('editor');
  };

  const handleEditPlan = (plan: WorkoutPlan | string) => {
      if (typeof plan === 'string') {
          // Special cases like warmup
          if (plan === '_warmup_') {
            // Construct a fake plan for the editor to modify warmup settings
            const warmupPlan: WorkoutPlan = {
                id: '_warmup_',
                name: 'Warmup Routine',
                steps: settings.warmupSteps,
                executionMode: 'linear'
            };
            setEditingPlan(warmupPlan);
            setIsWarmupEditor(true);
            setInitialEditorMode('edit');
            setView('editor');
          }
      } else {
          setEditingPlan(plan);
          setIsWarmupEditor(false);
          setInitialEditorMode('edit');
          setView('editor');
      }
  };

  const handleOpenAiPlanner = () => {
      setEditingPlan(null);
      clearEditorDraft();
      setInitialEditorMode('ai');
      setIsWarmupEditor(false);
      setView('editor');
  };

  const handleSavePlan = (plan: WorkoutPlan) => {
      if (isWarmupEditor) {
          updateSettings({ warmupSteps: plan.steps });
      } else {
          savePlan(plan);
      }
      setView('list');
      setEditingPlan(null);
  };

  const handleShowInfo = (plan: WorkoutPlan) => {
      setInfoPlan(plan);
  };

  return (
    <>
      <ExerciseInfoModal 
        exerciseName={inspectExerciseName} 
        isVisible={!!inspectExerciseName} 
        onClose={() => setInspectExerciseName(null)} 
      />
      {infoPlan && <WorkoutInfoModal plan={infoPlan} onClose={() => setInfoPlan(null)} />}

      {/* Menu Trigger Button */}
      <div className="absolute top-4 left-4 z-50 group hover:opacity-100 opacity-0 transition-opacity duration-300">
          <button
              onClick={() => setIsOpen(true)}
              className="p-2 rounded-full bg-gray-700/50 text-white hover:bg-gray-600 transition-colors shadow-lg"
              aria-label="Open Menu"
          >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
          </button>
      </div>

      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40"
          onClick={handleClose}
        ></div>
      )}

      <div 
        className={`fixed top-0 left-0 h-full w-full max-w-md bg-gray-800/95 backdrop-blur-md shadow-2xl z-50 transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className="h-full flex flex-col p-6">
            {/* Header */}
            <div className="flex justify-between items-center mb-6 shrink-0">
                <h2 className="text-2xl font-bold text-white">
                    {view === 'list' ? 'Workouts' : 
                     view === 'log' ? 'History' : 
                     view === 'editor' ? 'Editor' : 'Menu'}
                </h2>
                <button onClick={handleClose} className="p-2 rounded-full hover:bg-gray-700/50">
                    <svg className="w-6 h-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12"></path></svg>
                </button>
            </div>

            {/* Content Area */}
            <div className="flex-grow overflow-y-auto min-h-0 pr-2">
                {view === 'list' && (
                    <PlanList 
                        onSelectPlan={handleEditPlan}
                        onCreateNew={handleCreateNew}
                        onInitiateDelete={(id) => {
                            if(window.confirm("Are you sure you want to delete this plan?")) deletePlan(id);
                        }}
                        onShowLog={() => setView('log')}
                        onInspectExercise={setInspectExerciseName}
                        onShowInfo={handleShowInfo}
                        isPinned={isPinned}
                        onTogglePin={() => setIsPinned(!isPinned)}
                        onOpenAiPlanner={handleOpenAiPlanner}
                    />
                )}

                {view === 'editor' && (
                    <PlanEditor 
                        plan={editingPlan}
                        isWarmupMode={isWarmupEditor}
                        onSave={handleSavePlan} 
                        onCancel={() => {
                            setView('list');
                            setEditingPlan(null);
                        }}
                        initialMode={initialEditorMode}
                    />
                )}

                {view === 'log' && (
                    <WorkoutLog onBack={() => setView('list')} />
                )}
            </div>
        </div>
      </div>
    </>
  );
};

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { useLogger } from '../contexts/LoggingContext';

const CRASH_FLAG_KEY = 'app_crash_detected';

interface Props {
  children?: ReactNode;
  logError: (error: Error, componentStack: string) => void;
}

interface State {
  hasError: boolean;
}

/**
 * Internal class-based ErrorBoundary to use lifecycle methods.
 */
class ErrorBoundaryInternal extends Component<Props, State> {
  // Explicitly declare props to satisfy strict TS configurations if React types are ambiguous
  declare props: Readonly<Props>;

  public state: State = {
    hasError: false
  };

  static getDerivedStateFromError(_: Error): State {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
    this.props.logError(error, errorInfo.componentStack || '');

    try {
        localStorage.setItem(CRASH_FLAG_KEY, 'true');
    } catch (e) {
        console.error("Could not set crash flag in localStorage:", e);
    }
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="h-screen w-screen bg-red-900 text-white flex flex-col items-center justify-center p-4 text-center">
            <h1 className="text-4xl font-bold">התרחשה שגיאה</h1>
            <p className="mt-4 text-lg">אפליקציית השעון נתקלה בבעיה בלתי צפויה.</p>
            <p className="mt-2 text-md text-red-200">
                נסה לרענן את הדף. אם הבעיה נמשכת, אנא פתח את תפריט ההגדרות, עבור לקטע 'מפתחים' והעתק את פרטי ניפוי השגיאות כדי לדווח על הבעיה.
            </p>
            <button
                onClick={() => window.location.reload()}
                className="mt-8 px-6 py-3 bg-red-600 rounded-lg font-semibold hover:bg-red-700 transition-colors"
            >
                רענן דף
            </button>
        </div>
      );
    }

    return this.props.children;
  }
}

/**
 * Functional wrapper for the ErrorBoundary to consume hooks.
 */
export const ErrorBoundary: React.FC<{children: ReactNode}> = ({ children }) => {
    const { logError } = useLogger();
    return <ErrorBoundaryInternal logError={logError}>{children}</ErrorBoundaryInternal>;
};
